package com.gameaggregator.featureflagservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.featureflagservice.application.FeatureFlagService;import com.gameaggregator.featureflagservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/feature-flags") public class FeatureFlagController{final FeatureFlagService s;public FeatureFlagController(FeatureFlagService s){this.s=s;}@PostMapping ApiResponse<FeatureFlag> create(@Valid @RequestBody FeatureFlagDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<FeatureFlag>> list(){return ApiResponse.success(s.list());}@PutMapping("/{id}")ApiResponse<FeatureFlag> update(@PathVariable UUID id,@Valid @RequestBody FeatureFlagDtos.Update r){return ApiResponse.success(s.update(id,r));}@PutMapping("/{id}/overrides")ApiResponse<FeatureFlagOverride> override(@PathVariable UUID id,@Valid @RequestBody FeatureFlagDtos.OverrideRequest r){return ApiResponse.success(s.override(id,r));}@GetMapping("/evaluate/{key}")ApiResponse<FeatureFlagDtos.Evaluation> evaluate(@PathVariable String key,@RequestParam(required=false)UUID tenantId,@RequestParam(required=false)UUID environmentId,@RequestParam(required=false)UUID clientId){return ApiResponse.success(s.evaluate(key,tenantId,environmentId,clientId));}@GetMapping("/{id}/history")ApiResponse<List<FeatureFlagHistory>> history(@PathVariable UUID id){return ApiResponse.success(s.history(id));}}